foreach(['assets/images/Concepts','Concepts'] as $base){$dir=dirname(__DIR__).'/'.$base;if(!is_dir($dir))continue;foreach(scandir($dir) as $folder){if($folder[0]==='.'||!is_dir($dir.'/'.$folder))continue;$id=$slug($folder);if(!isset($styles[$id]))$styles[$id]=['id'=>$id,'name'=>$folder,'description'=>'Discover a considered interior design direction.','cover'=>null,'concepts'=>[]];foreach(scandir($dir.'/'.$folder) as $file){if(!is_file($dir.'/'.$folder.'/'.$file)||!preg_match('/\.(png|jpe?g|webp|avif)$/i',$file))continue;$src=$base.'/'.rawurlencode($folder).'/'.rawurlencode($file);$title=pathinfo($file,PATHINFO_FILENAME);if(strtolower($title)==='cover'){$styles[$id]['cover']??=$src;continue;}$room=preg_match('/kitchen/i',$title)?'Kitchen':(preg_match('/bedroom|wardrobe/i',$title)?'Bedroom':(preg_match('/living|media|tv[ _-]*wall/i',$title)?'Living Room':'Other'));$key=strtolower($file);$styles[$id]['concepts'][$key]??=['id'=>$id.'-'.substr(sha1($key),0,12),'title'=>$styles[$id]['name'].' '.$room,'filename'=>$file,'room'=>$room,'src'=>$src];}}}
